// Stations by their mean over the last 24 hours, in the map's colours, with
// their latest hour as a tick. Clicking a bar picks the station, as a click on
// the map does; clicking it again clears it.
const VAR = 'station';
const BREAKS = [5, 10, 15, 25];
const COLORS = ["#8A3413", "#AE461C", "#CC5D28", "#E07A3E", "#EE9A60"];
const colorOf = (v) => COLORS[BREAKS.filter((b) => v > b).length];

const chart = context.panel.chart;
const location = context.grafana.locationService;
const muted = context.grafana.theme.colors.text.secondary;
const text = context.grafana.theme.colors.text.primary;

const frame = context.panel.data.series[0];
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name).values) : []);
// ECharts draws a category axis bottom up: reversed, the highest is on top.
const ids = col('station').reverse();
const names = col('name').reverse();
const kinds = col('kind').reverse();
const means = col('mean_24h').reverse();
const lasts = col('last_no2').reverse();
const picked = context.grafana.replaceVariables('${' + VAR + '}');

chart.off('click');
chart.on('click', (event) => {
  const id = ids[event.dataIndex];
  const same = id === context.grafana.replaceVariables('${' + VAR + '}');
  location.partial({ ['var-' + VAR]: same ? '' : id }, true);
});

return {
  animation: false,
  grid: { left: 8, right: 40, top: 28, bottom: 24, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const i = items[0].dataIndex;
      const last = lasts[i] == null ? 'no reading' : `${lasts[i]} µg/m³`;
      return `<b>${names[i]}</b> · ${kinds[i]}<br/>24 h mean: <b>${means[i]} µg/m³</b><br/>Latest hour: ${last}`;
    },
  },
  xAxis: {
    type: 'value',
    name: 'µg/m³',
    nameLocation: 'end',
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  yAxis: {
    type: 'category',
    data: names,
    axisTick: { show: false },
    axisLabel: { color: text, fontSize: 11 },
  },
  series: [
    {
      type: 'bar',
      barWidth: '70%',
      cursor: 'pointer',
      data: means.map((v, i) => ({
        value: v,
        itemStyle: {
          color: colorOf(v),
          opacity: picked && picked !== ids[i] ? 0.35 : 1,
          borderRadius: [0, 4, 4, 0],
        },
      })),
      label: { show: true, position: 'right', color: muted, fontSize: 11, formatter: (p) => p.value.toFixed(0) },
      markLine: {
        silent: true,
        symbol: 'none',
        label: { formatter: 'WHO 24 h', color: muted, fontSize: 10 },
        lineStyle: { type: 'dashed', color: muted },
        data: [{ xAxis: 25 }],
      },
    },
    {
      type: 'scatter',
      name: 'Latest hour',
      symbol: 'rect',
      symbolSize: [2, 12],
      itemStyle: { color: text },
      data: lasts,
      tooltip: { show: false },
    },
  ],
};
